describe("buildBatchPack", () => {
  const packA = buildEvidencePack(base);
  const packB = buildEvidencePack({
    ...base,
    farmer: { ...base.farmer, full_name: "Chan Dara", farmer_code: "FRM-002" },
    contract: { contract_code: "CT-2", crop_type: "rice", season_label: "Wet 2026", signed_date: "2026-04-01" },
    parcels: [{ farm_code: "F-2", farm_name: "Field B", area_hectares: 3, boundary: square, land_tenure: "lease", land_tenure_ref: null }],
  });
  const batch = { batch_code: "B26-1", custody_model: "mass_balance" };

  it("keeps the delivered weight of the batch, not the sum of the contracts", () => {
    const bp = buildBatchPack({ batch, packs: [packA, packB], quantity_kg: 1500 });
    expect(bp.quantity_kg).toBe(1500);
  });

  it("lists every supplier and contract behind a mass-balance batch", () => {
    const bp = buildBatchPack({ batch, packs: [packA, packB], quantity_kg: 1500 });
    expect(bp.suppliers.map((s) => s.code).sort()).toEqual(["FRM-002", "FRM-073349"]);
    expect(bp.contract_codes.sort()).toEqual(["CT-1", "CT-2"]);
  });

  it("spans the production period of every contributing contract", () => {
    const bp = buildBatchPack({ batch, packs: [packA, packB], quantity_kg: 1500 });
    expect(bp.production_period.from).toBe("2026-04-01");
    expect(bp.production_period.to).toBe("2026-11-20");
  });

  it("deduplicates a plot that fed the batch through two contracts", () => {
    const bp = buildBatchPack({ batch, packs: [packA, packA], quantity_kg: 900 });
    expect(bp.plots).toHaveLength(1);
  });

  it("sums the practice evidence across contributing contracts", () => {
    const bp = buildBatchPack({ batch, packs: [packA, packB], quantity_kg: 1500 });
    expect(bp.practice.awd_cycles).toBe(packA.practice.awd_cycles + packB.practice.awd_cycles);
    expect(bp.practice.radar_passes).toBe(packA.practice.radar_passes + packB.practice.radar_passes);
  });

  it("calls the verdict mixed when contributing farmers disagree", () => {
    const clean = buildEvidencePack({ ...base, waterChecks: [{ agreement: "agrees" }] });
    const messy = buildEvidencePack({
      ...base,
      contract: { ...base.contract, contract_code: "CT-3" },
      waterChecks: [{ agreement: "disagrees" }],
    });
    const bp = buildBatchPack({ batch, packs: [clean, messy], quantity_kg: 100 });
    if (clean.practice.verdict !== messy.practice.verdict) {
      expect(bp.practice.verdict).toBe("mixed");
    }
  });

  it("reports readiness over the merged plots", () => {
    const unmapped = buildEvidencePack(withParcel({ boundary: null, area_hectares: 12 }));
    const bp = buildBatchPack({ batch: { batch_code: "B26-2", custody_model: "identity_preserved" }, packs: [unmapped], quantity_kg: 400 });
    const r = batchReadiness(bp);
    expect(r.ready).toBe(false);
    expect(r.missing.join(" ")).toMatch(/over 4 ha/);
  });

  it("blocks a batch nothing was delivered into", () => {
    const bp = buildBatchPack({ batch, packs: [packA], quantity_kg: 0 });
    expect(batchReadiness(bp).missing.join(" ")).toMatch(/delivered into this batch/);
  });
});

import { describe, expect, it } from "vitest";
import {
  CUSTODY_MODELS,
  DEFAULT_CUSTODY,
  DEFAULT_KG_PER_BAG,
  MOISTURE_STAGES,
  STAGES,
  batchMath,
  estimatedWeight,
  isEstimated,
  mixesFarmers,
  stageLabel,
  stageTotals,
  varietyBlocks,
  type WeighPointLite,
} from "./batch-core";

const wp = (stage: string, weight_kg: number, moisture_pct: number | null = null): WeighPointLite => ({
  stage,
  weight_kg,
  moisture_pct,
});

describe("stageTotals", () => {
  it("sums repeated stages", () => {
    const t = stageTotals([wp("received", 500), wp("received", 300), wp("post_drying", 640)]);
    expect(t.received).toBe(800);
    expect(t.post_drying).toBe(640);
    expect(t.into_mill).toBeUndefined();
  });
  it("empty ledger", () => {
    expect(stageTotals([])).toEqual({});
  });
});

describe("batchMath", () => {
  it("drying loss measured from received vs post_drying", () => {
    const m = batchMath([wp("received", 11840, 26), wp("post_drying", 9472, 13.5)]);
    expect(m.dryingLossPct).toBeCloseTo(20.0);
    expect(m.moistureBeforeDrying).toBe(26);
    expect(m.moistureAfterDrying).toBe(13.5);
  });
  it("milling recovery and fractions of into_mill", () => {
    const m = batchMath([
      wp("into_mill", 1000),
      wp("milled_output", 620),
      wp("bran", 90),
      wp("husk", 200),
      wp("wastage", 40),
    ]);
    expect(m.millingRecoveryPct).toBeCloseTo(62);
    expect(m.branPct).toBeCloseTo(9);
    expect(m.huskPct).toBeCloseTo(20);
    expect(m.outputsExceedInput).toBe(false);
    // 620+90+200+40 = 950 -> 50 kg unaccounted
    expect(m.unaccountedKg).toBeCloseTo(50);
  });
  it("flags outputs exceeding mill input", () => {
    const m = batchMath([wp("into_mill", 1000), wp("milled_output", 700), wp("bran", 200), wp("husk", 200)]);
    expect(m.outputsExceedInput).toBe(true);
  });
  it("null metrics when stages missing", () => {
    const m = batchMath([wp("received", 500)]);
    expect(m.dryingLossPct).toBeNull();
    expect(m.millingRecoveryPct).toBeNull();
    expect(m.branPct).toBeNull();
    expect(m.outputsExceedInput).toBe(false);
    expect(m.unaccountedKg).toBeNull();
  });
  it("zero received guards division", () => {
    const m = batchMath([wp("received", 0), wp("post_drying", 0)]);
    expect(m.dryingLossPct).toBeNull();
  });
  it("moisture picks latest non-null reading per side", () => {
    const m = batchMath([wp("received", 500, null), wp("received", 300, 25), wp("post_drying", 640, null)]);
    expect(m.moistureBeforeDrying).toBe(25);
    expect(m.moistureAfterDrying).toBeNull();
  });
});

describe("mixesFarmers", () => {
  it("true when two distinct farmers", () => {
    expect(mixesFarmers(["a", "b"])).toBe(true);
  });
  it("false for one farmer repeated or empty", () => {
    expect(mixesFarmers(["a", "a"])).toBe(false);
    expect(mixesFarmers([])).toBe(false);
  });
});

describe("labels", () => {
  it("every stage has a label", () => {
    for (const s of STAGES) expect(stageLabel(s.value)).toBeTruthy();
  });
  it("unknown stage falls back to raw value", () => {
    expect(stageLabel("weird")).toBe("weird");
  });
});

describe("mill flow stages (mill manager, 8 Sep 2026)", () => {
  it("stage order follows the floor: received, pre_dried, post_drying, into_storage, into_mill", () => {
    const order = STAGES.map((s) => s.value);
    expect(order.slice(0, 5)).toEqual(["received", "pre_dried", "post_drying", "into_storage", "into_mill"]);
    expect(MOISTURE_STAGES).toEqual(["received", "pre_dried", "post_drying", "into_mill"]);
  });
  it("pre-dry moisture is reported separately from final moisture", () => {
    const m = batchMath([wp("received", 10000, 25), wp("pre_dried", 9000, 16.5), wp("post_drying", 8200, 14)]);
    expect(m.moistureAfterPreDry).toBe(16.5);
    expect(m.moistureAfterDrying).toBe(14);
    expect(m.dryingLossPct).toBeCloseTo(18);
  });
  it("estimated weight = bags × kg per bag, default 675", () => {
    expect(DEFAULT_KG_PER_BAG).toBe(675);
    expect(estimatedWeight(18, 675)).toBe(12150);
    expect(estimatedWeight(0, 675)).toBe(0);
  });
  it("stored and in-store come from into_storage minus into_mill", () => {
    const m = batchMath([
      wp("post_drying", 12000, 14),
      { ...wp("into_storage", 12150), estimated: true },
      wp("into_mill", 4000),
    ]);
    expect(m.storedKg).toBe(12150);
    expect(m.inStoreKg).toBe(8150);
    expect(m.estimatedStages).toEqual(["into_storage"]);
  });
  it("in-store is null without an into_storage point and never negative", () => {
    expect(batchMath([wp("post_drying", 100)]).inStoreKg).toBeNull();
    expect(batchMath([wp("into_storage", 100), wp("into_mill", 130)]).inStoreKg).toBe(0);
  });
  it("isEstimated says whether a figure rests on an estimate", () => {
    const m = batchMath([{ ...wp("received", 1000), estimated: true }, wp("post_drying", 800)]);
    expect(isEstimated(m, "received", "post_drying")).toBe(true);
    expect(isEstimated(m, "into_mill", "milled_output")).toBe(false);
  });
  it("variety guard blocks only when both sides are set and differ", () => {
    expect(varietyBlocks("Sen Kra Ob", "Phka Rumduol")).toBe(true);
    expect(varietyBlocks("Sen Kra Ob", "sen kra ob ")).toBe(false);
    expect(varietyBlocks(null, "Sen Kra Ob")).toBe(false);
    expect(varietyBlocks("Sen Kra Ob", null)).toBe(false);
  });
  it("mixed is the default custody, listed first", () => {
    expect(DEFAULT_CUSTODY).toBe("mass_balance");
    expect(CUSTODY_MODELS[0].value).toBe("mass_balance");
  });
});

import { describe, expect, it } from "vitest";
import { imageryLabel, isDrySeasonMonth, summariseImagery, type ImageryCapture } from "./imagery-date";

const cap = (date: string, resM: number | null = 0.34, source: string | null = "Vivid"): ImageryCapture => ({
  date,
  resM,
  source,
});

describe("isDrySeasonMonth", () => {
  it("covers Nov through Apr", () => {
    expect([11, 12, 1, 2, 3, 4].every(isDrySeasonMonth)).toBe(true);
    expect([5, 6, 7, 8, 9, 10].some(isDrySeasonMonth)).toBe(false);
  });
});

describe("summariseImagery", () => {
  it("spans the oldest and newest capture in the mosaic", () => {
    // The real estate today: three passes stitched across fourteen months.
    const s = summariseImagery([cap("2026-02-17"), cap("2025-02-17"), cap("2026-04-24")])!;
    expect(s.from).toBe("2025-02");
    expect(s.to).toBe("2026-04");
    expect(s.allDrySeason).toBe(true);
  });

  it("collapses a single-pass mosaic to one month", () => {
    const s = summariseImagery([cap("2026-02-17"), cap("2026-02-17")])!;
    expect(s.from).toBe("2026-02");
    expect(s.to).toBe("2026-02");
  });

  it("reports the sharpest source, not the first", () => {
    const s = summariseImagery([cap("2025-01-02", 1.2, "Coarse"), cap("2026-03-04", 0.34, "Vivid")])!;
    expect(s.resM).toBe(0.34);
    expect(s.source).toBe("Vivid");
  });

  it("drops the dry-season claim when any pass is from the wet season", () => {
    expect(summariseImagery([cap("2026-02-17"), cap("2026-08-01")])!.allDrySeason).toBe(false);
  });

  it("returns null when nothing resolved", () => {
    expect(summariseImagery([])).toBeNull();
    expect(summariseImagery([cap("")])).toBeNull();
  });
});

describe("imageryLabel", () => {
  it("reads as one honest line", () => {
    const s = summariseImagery([cap("2025-02-17"), cap("2026-04-24")])!;
    expect(imageryLabel(s, "Basemap", "dry season")).toBe("Basemap 2025-02 – 2026-04 · Vivid 0.3 m · dry season");
  });

  it("omits the range when the mosaic is one pass", () => {
    const s = summariseImagery([cap("2026-02-17")])!;
    expect(imageryLabel(s, "Basemap", "dry season")).toBe("Basemap 2026-02 · Vivid 0.3 m · dry season");
  });
});

