describe("in store and mill next (mill manager, 8 Sep 2026)", () => {
  it("in store prefers into_storage over post_drying and carries the estimate", () => {
    const s = stockSnapshot([], [bv("b1", "B1", "Sen Kra Ob", "2026-11-01")], [
